jmp_buf env;

void error_exit(int code) {
    // Non-local jump returns to setjmp
    // Execution stack unwound
    longjmp(env, code);
}

int try_block() {
    int ret = setjmp(env);

    if (ret == 0) {
        // Initial call (Try block setup)
        // ... perform operations
        error_exit(42); // Initiate jump
        // unreachable
    } else {
        // Return via longjmp (Catch block)
        // ret == 42
        return ret;
    }
}
